def components(A, diag=False):
 H,W=A.shape; seen=set(); comps=[]
 dirs=[(di,dj) for di in [-1,0,1] for dj in [-1,0,1] if (di,dj)!=(0,0) and (diag or abs(di)+abs(dj)==1)]
 for i,j in zip(*np.where(A==0)):
  if (i,j) in seen: continue
  c={(i,j)};seen.add((i,j));q=[(i,j)]
  while q:
   y,x=q.pop()
   for di,dj in dirs:
    p=(y+di,x+dj)
    if 0<=p[0]<H and 0<=p[1]<W and A[p]==0 and p not in seen: seen.add(p);c.add(p);q.append(p)
  comps.append(c)
 return comps
for diag in [False,True]:
 comps=components(A,diag)
 print('diag',diag,'n',len(comps))
 for c in comps:
  coords=list(c); nout=sum(B[p]==1 for p in coords); nin=sum(A[p]==1 for p in coords)
  # marker-adjacent
  adj=any(max(abs(i-y),abs(j-x))<=1 for i,j in c for y,x in zip(*np.where(A==1)))
  if nout: print('size',len(c),'new1',nout,'adjacent',adj,'bbox',(min(i for i,j in c),max(i for i,j in c),min(j for i,j in c),max(j for i,j in c)))

def paint_rule(A, fg):
 out=A.copy(); H,W=A.shape
 for i in range(H-1):
  for j in range(W-1):
   block=A[i:i+2,j:j+2]
   if np.sum(block==0)>=3:
    out[i:i+2,j:j+2][block==0]=fg
 return out
