def template_rule(A, points, fg):
 out=A.copy(); H,W=A.shape
 for i in range(H-1):
  for j in range(W-1):
   ps=[(i+di,j+dj) for di,dj in points]
   if all(A[p]==0 for p in ps):
    for p in ps:out[p]=fg
 return out
